// @ts-nocheck
import { Copy, Terminal } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { notify, notifyError } from '../../lib/notify';
import { sendSqlToTerminal } from '../../lib/sendSqlToTerminal';

export function SqlScriptActions({
  sql,
  connectionId,
  database,
  copyLabel,
  showTerminal = true,
}) {
  const { t } = useTranslation(['common', 'ops']);
  const text = String(sql ?? '').trim();
  if (!text) return null;
  const label = copyLabel ?? t('common:copy');

  const onCopy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      notify(t('common:copied'));
    } catch {
      notifyError(new Error(t('ops:copyFailed')));
    }
  };

  const onTerminal = () => {
    if (!connectionId) {
      notifyError(new Error(t('ops:noActiveConnection')));
      return;
    }
    sendSqlToTerminal({ connectionId, database, sql: text });
  };

  return (
    <div className="flex flex-wrap gap-1">
      <button type="button" className="nv-btn !text-2xs" onClick={onCopy}>
        <Copy size={10} /> {label}
      </button>
      {showTerminal && connectionId && (
        <button type="button" className="nv-btn !text-2xs" onClick={onTerminal}>
          <Terminal size={10} /> {t('ops:sendToSqlTerminal')}
        </button>
      )}
    </div>
  );
}
